import math

def solve():
    alpha = math.sqrt(2)
    k = 1
    cool_pairs = []
    for m in range(1, 20):
        for n in range(1, 20):
            if m * math.ceil(n * alpha) - n * math.floor(m * alpha) == k:
                is_cool = True
                if m > n:
                    if m - n > 0 and (m - n) * math.ceil(n * alpha) - n * math.floor((m - n) * alpha) == k:
                        is_cool = False
                if n > m:
                    if n - m > 0 and m * math.ceil((n - m) * alpha) - (n - m) * math.floor(m * alpha) == k:
                        is_cool = False
                if is_cool:
                    cool_pairs.append((m, n))
    return cool_pairs

